INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (2780, 'Chùa Dơi Sóc Trăng | NGUỒN GỐC và BÍ ẨN của những con DƠI', 'chua-doi', '
<p>Chùa Dơi Sóc Trăng là một ngôi chùa đặc biệt bởi các con dơi sinh sống trong khuôn viên chùa. Thật ra cái tên chùa Dơi là do dân gian gọi tên để dễ nhớ hơn. Còn cái tên thật của nó là <strong>Serây tê chô mahatúp</strong> (Còn có nghĩa tiếng Việt là Trận Kháng Cự Lớn). Đây là một ngôi chùa Khmer linh thiêng có lịch sử lâu đời. Nó cũng là một điểm du lịch tâm linh và tìm hiểu kiến trúc chùa ở Sóc Trăng độc đáo.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bên-ngoài-khuôn-viên-chùa-cũng-có-thờ-tượng-phật-thích-ca-1024x853.jpg" alt="Bên ngoài khuôn viên chùa cũng có thờ tượng Phật Thích Ca" class="wp-image-3443"/><figcaption>Bên ngoài khuôn viên chùa cũng có thờ tượng Phật Thích Ca</figcaption></figure>



<h2 class="wp-block-heading">Lịch sử Chùa Dơi Sóc Trăng</h2>



<p>Chùa Dơi là một ngôi chùa có lịch sử lâu đời của <a rel="noreferrer noopener nofollow" aria-label="Đồng bằng sông Cửu Long (mở trong tab mới)" href="https://vi.wikipedia.org/wiki/%C4%90%E1%BB%93ng_b%E1%BA%B1ng_s%C3%B4ng_C%E1%BB%ADu_Long" target="_blank">Đồng bằng sông Cửu Long</a> với lịch sử gần 450 năm. Chùa được khởi công xây dựng từ năm 1569. Sau nhiều lần trùng tu và sửa chữa vào các năm 1960 và lần gần nhất là vào năm 2009. Đặc biệt vào năm 1999, chùa Dơi đã được cấp chứng nhận là di tích lịch sử &#8211; văn hóa cấp quốc gia.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bà-đen-ở-chùa-dơi-sóc-trăng-1024x853.jpg" alt="Bà Đen ở chùa Dơi Sóc Trăng" class="wp-image-3441"/><figcaption>Bà Đen ở chùa Dơi Sóc Trăng</figcaption></figure>



<h2 class="wp-block-heading">Nguồn gốc chùa Dơi Sóc Trăng</h2>



<p>Chùa dơi tên nguyên bản là Serây tê chô mahatúp. Theo phiên âm của người Khmer: Maha là lớn, còn Túp là trận kháng cự, ghép lại là trận kháng cự lớn. Theo lời kể của các bô lão ở đây, thuở bấy giờ nơi đây thường hay nổ ra các tranh chấp giữa người nông dân và chính quyền phong kiến. Nơi này là chỗ dựa tinh thần của người dân trong các trận kháng chiến lớn.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/ban-nhạc-cụ-truyền-thống-ở-chùa-dơi-sóc-trăng-1024x853.jpg" alt="Ban nhạc cụ truyền thống ở chùa Dơi" class="wp-image-3442"/><figcaption>Ban nhạc cụ truyền thống ở chùa Dơi</figcaption></figure>



<p>Địa điểm này thuở bấy giờ là kết tinh tinh thần của người dân cả vùng. Người dân cho rằng đây là một vùng đất lành, nên đã cùng nhau dựng nên một ngôi chùa và đặt tên Mahatup. Người đại diện đứng ra xây dựng là ông Thạch Út. Đến nay thì đã trả qua 19 đời Đại Đức làm chủ trì chùa.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chùa-dơi-có-nhiều-nơi-thờ-phật-thích-ca-1024x853.jpg" alt="Chùa Dơi có nhiều nơi thờ Phật Thích Ca" class="wp-image-3451"/><figcaption>Chùa Dơi có nhiều nơi thờ Phật Thích Ca</figcaption></figure>



<p>Cái tên chùa Dơi thì do người dân gần đó gọi vì nơi đây có hàng nghìn con dơi sinh sống ở khuôn viên. Gần như chùa Dơi chính là tổ dơi lớn nhất ở Sóc Trăng. Nơi những con dơi treo mình trên cây ngủ vào buổi sáng và chiều tối đi tìm thức ăn là trái cây ở các vườn xung quanh. Đặc biệt, chúng hoàn toàn không sợ tiếng gõ mõ hay tiếng ồn khách du lịch.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/vườn-cây-nơi-những-con-dơi-ngựa-trú-ẩn-ở-chùa-dơi-1024x853.jpg" alt="Vườn cây nơi những con dơi ngựa trú ẩn ở chùa Dơi" class="wp-image-3469"/><figcaption>Vườn cây nơi những con dơi ngựa trú ẩn ở chùa Dơi</figcaption></figure>



<h2 class="wp-block-heading">Chuyện những con dơi sinh sống trong khuôn viên chùa</h2>



<p>Dơi là loài vật thiêng liêng, mang ý nghĩa đặc biệt theo quan niệm thời xưa.</p>



<h3 class="wp-block-heading">Đặc điểm loài dơi ở chùa Dơi (Mahatup)</h3>



<p>Dơi ở chùa gồm hai loại là dơi ngựa Thái Lan và <a rel="noreferrer noopener nofollow" aria-label="dơi ngựa (mở trong tab mới)" href="https://vi.wikipedia.org/wiki/D%C6%A1i_qu%E1%BA%A1_l%E1%BB%9Bn" target="_blank">dơi ngựa</a> lớn. Chúng sống ở đây từ trước cả lúc xây chùa. Hiện những loài dơi này đã được đưa vào sách đỏ Việt Nam và nghiêm cấm săn bắt.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chùa-dơi-sóc-trăng-có-sân-vườn-rộng-rãi-1024x853.jpg" alt="Chùa dơi Sóc Trăng có sân vườn rộng rãi" class="wp-image-3456"/><figcaption>Chùa dơi Sóc Trăng có sân vườn rộng rãi</figcaption></figure>



<p>Khối lượng những con dơi ngựa ở đây từ 500gr &#8211; 1100gr/con. Cách của chúng khi căng ngang có chiều dài 1,1m đến 1,5m. Tốc độ tối đa khi bay có thể lên đến 50 &#8211; 60km/h. Chúng là loài động vật có vú, miệng có răng bén để gặm trái cây và miệng nhọn như loài chó phốc. Chân chúng có 5 ngón và nhọn như hình móc câu, chân chúng khá là khỏe. Khi ngủ, chúng móc chân vào cành cây và treo ngược lủng lẳng lên thân cây.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/những-con-dơi-treo-lủng-lẳng-trên-cây-ở-chùa-dơi-1024x853.jpg" alt="Những con dơi treo lủng lẳng trên cây ở chùa Dơi" class="wp-image-3464"/><figcaption>Những con dơi treo lủng lẳng trên cây ở chùa Dơi</figcaption></figure>



<p>Mùa sinh sản của loài dơi ngựa này thường khoảng đầu xuân. Vì dơi là loài động vật có vú nên chúng không đẻ trứng mà đẻ con. Nên chúng không cần làm tổ như loài chim khác. Khi đẻ chúng vẫn treo thân mình lủng lẳng trên cây. Một cánh móc lấy cành cây, một cánh còn lại đỡ lấy đứa con sắp chào đời. Thông thường vào khoảng tháng thứ 3 dơi con sẽ bắt đầu biết bay và gia nhập chính thức vào bầy đàn để đi tìm thức ăn.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chùa-dơi-cũng-có-thờ-những-con-chó-đá-1024x853.jpg" alt="Chùa Dơi cũng có thờ những con chó đá" class="wp-image-3453"/><figcaption>Chùa Dơi cũng có thờ những con chó đá</figcaption></figure>



<p>Trước đây, những người nông dân cũng thường lấy mùa sinh sản của dơi để làm mùa cấy lúa. Những con dơi được sinh ra, phúc lộc đâm chồi. Lúc ấy vừa vào mùa vụ mới, bắt đầu những điều mới.</p>



<p>Khi đi vệ sính, chúng dùng cánh bật thân thể lên. Sau đó, như một vòi nước bắn tất cả ra ngoài. Khi đi dưới những nơi con dơi ở, bạn hãy cẩn thận nếu bắt gặp chúng tung mình dùng hai cánh làm trụ. Đó không phải tập thể dục, nâng xa đâu, mà là&#8230;</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bộ-nhạc-cụ-dân-tộc-lưu-trữ-ở-chùa-dơi-sóc-trăng-1024x853.jpg" alt="Bộ nhạc cụ dân tộc lưu trữ ở chùa Dơi Sóc Trăng" class="wp-image-3444"/><figcaption>Bộ nhạc cụ dân tộc lưu trữ ở chùa Dơi Sóc Trăng</figcaption></figure>



<h3 class="wp-block-heading">Quan niệm về điềm phúc của loài dơi</h3>



<p>Trong quan điểm tứ linh của người Hoa kinh doanh thì phải là Long Lân Bức Phụng. Bức ở đây chỉ loài dơi. Quy chỉ phù hợp với người làm quan, với thương gia, loài dơi khá chậm chạp không thích hợp vận làm ăn.</p>



<p>Khi con dơi treo ngược trên cành cây, thân hình chúng tương ứng với chữ Phúc. Người ta cho rằng đó là biểu tượng phúc đáo, phúc vào nhà nên dơi luôn là điềm đại cát đại lợi. Đặc biệt những loài dơi ở chùa dơi luôn rất gần gũi với con người.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/phía-sau-chánh-điện-có-hồ-nước-và-cây-xanh-thoáng-mát-1024x853.jpg" alt="Phía sau chánh điện có hồ nước và cây xanh thoáng mát" class="wp-image-3466"/><figcaption>Phía sau chánh điện có hồ nước và cây xanh thoáng mát</figcaption></figure>



<p>Từng có lúc những con dơi ở đây luôn đi theo một vị Đại Đức chủ trì chùa. Ông xem chúng như là những người bạn yêu quý. Những con dơi đó đôi khi ngủ lại cả trong phòng ông. Hàng ngày nghe tụng kinh gõ mõ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="907" src="https://media.huynhhieutravel.com/chùa-dơi-ở-sóc-trăng-1024x907.jpg" alt="Chùa dơi ở Sóc Trăng" class="wp-image-3454"/><figcaption>Chùa dơi ở Sóc Trăng</figcaption></figure>



<p>Đặc biệt, Sóc Trăng là vùng nhiều vườn trái cây. Nhưng không hiểu sao loài dơi thường chỉ thích ở trong chùa Dơi. Chúng ít khi ăn trái cây trong vườn. Cứ vào khoảng 6h00 &#8211; 7h00 chúng bay ra ngoài vườn xa để kiếm ăn. Khi bay, chúng thường bay vòng qua chánh điện chứ hiếm khi bay thẳng ngang đó. Dường như có điềm linh thiêng bao bọc lấy ngôi chùa và chúng vô cùng kính ngưỡng.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/bức-hình-vẽ-Phật-giảng-đạo-dưới-gốc-bồ-đề-1024x853.jpg" alt="Bức hình vẽ Phật giảng đạo dưới gốc cây bồ đề" class="wp-image-3445"/><figcaption>Bức hình vẽ Phật giảng đạo dưới gốc cây bồ đề</figcaption></figure>



<h3 class="wp-block-heading">Chuyện về loài heo năm mống</h3>



<p>Heo năm mống hay heo &#8220;ba giò&#8221; là những thứ linh thiêng mà người dân Khmer sợ hãi khi nhắc đến. Heo ba giò ở đây không phải là chỉ có ba chiếc giò mà là 3 giò có một màu và giò còn lại có màu khác</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chùa-dơi-tỉnh-sóc-trăng-1024x853.jpg" alt="Chùa Dơi tỉnh Sóc Trăng" class="wp-image-3457"/><figcaption>Chùa Dơi tỉnh Sóc Trăng</figcaption></figure>



<p>Người Khmer quan niệm, con heo nào mang yếu tố như vậy là cốt tinh của người. Kiếp trước người đó làm nhiều điều ác nên đầu thay thành heo năm mống. Người ở đây quan niệm heo năm mống là những linh hồn ác kiếp trước. Nên khi nuôi chúng, gia đình đó phải chịu tai kiếp và xui xẻo. Nhưng nếu giết chúng thì gia đình sẽ gặp điều bất hạnh to lớn hoặc có thể chết đi.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/cổng-chùa-dơi-1024x853.jpg" alt="Cổng chùa Dơi" class="wp-image-3458"/><figcaption>Cổng chùa Dơi</figcaption></figure>



<p>Chính vì vậy, đưa heo năm mống vào chùa để giải tai ương là điều mà bà con xung quanh hay làm. Họ mong với phúc đức của chùa sẽ giải đi linh hồn tội lỗi và giúp cốt tinh đó nhanh đầu thai thành người. Hàng ngày, những con heo đó được nghe những kinh kệ, sám hối nơi cửa Phật. Nó sẽ không còn đi mang tai họa đến người khác nữa. Từ đó chùa Dơi trở thành nơi nuôi dưỡng những con heo quái dị cho người dân.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="1024" src="https://media.huynhhieutravel.com/chùa-dơi-có-nhiều-tòa-tháp-đặc-trưng-chùa-khmer-1024x1024.jpg" alt="Chùa Dơi có nhiều tòa tháp đặc trưng chùa Khmer" class="wp-image-3452" srcset="https://media.huynhhieutravel.com/chùa-dơi-có-nhiều-tòa-tháp-đặc-trưng-chùa-khmer-1024x1024.jpg 1024w, https://media.huynhhieutravel.com/chùa-dơi-có-nhiều-tòa-tháp-đặc-trưng-chùa-khmer-150x150.jpg 150w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Chùa Dơi có nhiều tòa tháp đặc trưng chùa Khmer</figcaption></figure>



<p>Con heo 5 mống đầu tiên mà nhà chùa nuôi dưỡng là vào năm 1989. Truyện kể rằng trong chùa trước đây có một bà cụ tên Khiên. Cụ Khiên làm nhiệm vụ quét dọn, trông nom cửa chùa cho các sư thầy tu tập. </p>



<p>Một hôm khi quét dọn, bà Khiên mệt mỏi nên ngủ thiếp đi bên cửa chùa. Bà Khiên năm mơ thấy Bồ Tát hiển linh báo mộng. Nói rằng ngày hôm sau, sẽ có một cô gái đến xin quy y, nương nhờ cửa Phật để tu tâm. Bà Khiên sau khi tỉnh giấc, đã thắp nhang và mong chờ vị nữ thí chủ sẽ đến vào ngày hôm sau.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/đức-phật-được-nhiều-người-tin-rằng-sẽ-nổi-bật-dù-còn-nhỏ-1024x853.jpg" alt="Đức Phật được nhiều người tin rằng sẽ nổi bật dù còn nhỏ" class="wp-image-3459"/><figcaption>Đức Phật được nhiều người tin rằng sẽ nổi bật dù còn nhỏ</figcaption></figure>



<p>Sáng hôm sau, bà Khiên dậy sớm trông chờ. Nhưng lạ thay, hôm đó cửa chùa vẫn vắng khách. Không có người nào đến xin quy y cửa phật. Bà Khiên cho rằng mình đã nằm mơ không linh. Chiều tối đến, bà cầm chổi quét dọn sân chùa và làm sạch cỏ dạy như thường lệ. Bất ngờ thay bà phát hiện phía sau vườn là một con heo cái năm mống đang nằm ngủ ngon lành.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/trong-chánh-điện-cón-nhiều-bức-hình-mô-tả-lại-cuộc-đời-đức-Phật-1024x853.jpg" alt="Trong chánh điện có nhiều bức hình mô tả lại cuộc đời đức Phật" class="wp-image-3468"/><figcaption>Trong chánh điện có nhiều bức hình mô tả lại cuộc đời đức Phật</figcaption></figure>



<p>Thế là bà biết rằng vị nữ thí chủ mà Bồ Tát nói đến chính là nàng heo này. Mọi người cũng bảo rằng đó là điềm báo của Phật để giải nghiệp oán cho nàng heo. Thế là mọi người cùng bà Khiên bắt đầu làm lễ nhận nàng heo năm móng quy y đúng như nghi lễ. Đặt tên pháp danh cho nàng heo này là &#8220;Năm Hợi&#8221;. Và cũng từ đó, sau này những người dân làng xung quanh hễ có heo năm móng sinh ra đều dẫn lại chùa nhờ nuôi.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/lối-vào-chánh-điện-chùa-dơi-sóc-trăng-1024x853.jpg" alt="Lối vào chánh điện chùa Dơi Sóc Trăng" class="wp-image-3462"/><figcaption>Lối vào chánh điện chùa Dơi Sóc Trăng</figcaption></figure>



<p>Sau này khi Năm Hợi chết, các sư thầy cho mai táng sau chùa như thủ tục người chết bình thường. Mọi người dân khi hay tin đều đến đốt nhang cúng viếng cô. Một ngày sau, bỗng có một người phụ nữ đến từ Sài Gòn tìm đến chùa. Người phụ nữ bảo rằng mẹ cô sau khi mất đã tìm về báo tin rằng bà đã hóa thành kiếp heo. Hiện đã trả xong nghiệp báo và đầu thai.</p>



<p>Người phụ nữ đó mong các sư cho phép làm lễ cầu siêu để linh hồn mẹ cô đầu thai an lành. Sau khi cầu siêu xong, người phụ nữ đã cho lập bia, vẽ hình một chú heo lên và đề tên Năm Hợi vào bia mộ. Sau này khi có heo chết, những người nhà gửi heo đều học theo làm bia mộ cho những chú heo năm móng đó. Phía sau chùa Dơi xuất hiện một nghĩa địa heo năm móng là như vậy.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chùa-có-khuôn-viên-rộng-rãi-1024x853.jpg" alt="Chùa có khuôn viên rộng rãi" class="wp-image-3448"/><figcaption>Chùa có khuôn viên rộng rãi</figcaption></figure>



<h2 class="wp-block-heading">Kiến trúc chùa Dơi Sóc Trăng</h2>



<p>Chùa Dơi ở Sóc Trăng là một ngôi chùa Khmer điển hình. Tổng thể kiến trúc chùa bao gồm: Chánh điện, Sala, phòng các thầy sư và phòng tín đồ, phòng trụ trì, phòng các vị sư khác, phòng khách, tháp để tro cốt người, nghĩa địa, hồ nước và cả một khu vườn lớn. Khu vườn cũng là nơi trú chân của hàng nghìn con dơi ngựa của chùa.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/khuôn-viên-chùa-dơi-khá-nhiều-cây-xanh-1024x853.jpg" alt="Khuôn viên chùa dơi khá nhiều cây xanh" class="wp-image-3460"/><figcaption>Khuôn viên chùa dơi khá nhiều cây xanh</figcaption></figure>



<p>Chánh điện được xây bằng gạch, mái ngói được lợp cong vút lên cao với hình tượng rắn naga, đỉnh mái là tháp nhọn. Xung quanh chánh điện là các cột hình tiên nữ Kemmar chấp hai tay trước ngực. </p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/mái-chánh-điện-chùa-dơi-được-thiết-kế-đặc-biệt-1024x853.jpg" alt="Mái chánh điện chùa Dơi được thiết kế đặc biệt" class="wp-image-3463"/><figcaption>Mái chánh điện chùa Dơi được thiết kế đặc biệt</figcaption></figure>



<p>Bên trong chánh điện là pho tượng Phật bằng đá ngồi trên tòa sen cao khoảng 2m và một pho tượng khác mô tả đức Phật cưỡi trên thần rắn Muchalinda. Trên 4 bức tường là những hình vẽ mô tả về cuộc đời đức Phật. Từ khi sinh ra đến lúc người lớn lên, chiêm nghiệm cuộc đời và ngồi dưới gốc cây bồ đề niết bàn thành Phật.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/cảnh-đức-Phật-bước-bảy-bước-nở-bảy-hoa-sen-1024x853.jpg" alt="Cảnh đức Phật bước bảy bước nở bảy hoa sen" class="wp-image-3446"/><figcaption>Cảnh đức Phật bước bảy bước nở bảy hoa sen</figcaption></figure>



<p>Mỗi một bảo tháp ở sân chùa đều chứa các di hài của trụ trì đời trước. Sala là kiểu nhà rông, là nơi nghỉ ngơi và tu học riêng tư của các sư. Phía sau vườn là những ngôi mộ heo năm mống mà tôi đã kể về sự tích của chúng ở trên. Chùa cũng còn nuôi một số con heo năm mống trong khuôn viên.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/cảnh-đức-phật-quyết-cắt-tóc-tham-ngộ-con-đường-giải-thoát-1024x853.jpg" alt="Cảnh đức Phật quyết cắt tóc tham ngộ con đường giải thoát" class="wp-image-3447"/><figcaption>Cảnh đức Phật quyết cắt tóc tham ngộ con đường giải thoát</figcaption></figure>



<p>Cổng chùa được xây nhìn về hướng Tây Bắc, trang trí cách điệu với họa tiết cánh sen và hoa cà ri được cách điệu. Xung quanh sân vườn có nhiều cây cổ thụ được trồng. Buổi trưa rợp bóng mát, mỗi lần gió thổi ngang lại rì rào như đang hát ca.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chùa-dơi-1024x853.jpg" alt="Chùa Dơi" class="wp-image-3449"/><figcaption>Chùa Dơi</figcaption></figure>



<h2 class="wp-block-heading">Du lịch chùa Dơi</h2>



<p>Bạn có thể tham quan ngôi chùa Dơi nổi tiếng này miễn phí. Nếu đi xe lớn bạn phải đi xe điện đón đến chùa với chi phí 10.000đ/vé khứ hồi. Phí gửi xe máy là 7000đ/xe.</p>



<h3 class="wp-block-heading">Mua gì ở chùa Dơi?</h3>



<p>Đến chùa Dơi bạn có thể mua các loại khô khác nhau trước cổng chùa. Vì là chùa Khmer nên thường sư ở đây sẽ không ăn chay. Quan niệm ở chùa Khmer là người dân cho gì họ sẽ ăn đó chứ không lựa chọn.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/trên-trần-là-những-hình-vẽ-về-cuộc-đời-đức-Phật-1024x853.jpg" alt="Trên trần là những hình vẽ về cuộc đời đức Phật" class="wp-image-3467"/><figcaption>Trên trần là những hình vẽ về cuộc đời đức Phật</figcaption></figure>



<p>Bạn cũng có thể thưởng thức những trái dừa nước trái nhỏ ở trước cổng chùa. Trưa nắng oi bức, tham quan chùa Dơi rồi làm một quả dừa mát lạnh thì thật tuyệt vời. Dừa ở đây vị ngọt, thanh, uống vào rất mát.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/chùa-dơi-chỉ-thờ-duy-nhất-phật-thích-ca-1024x853.jpg" alt="Chùa dơi chỉ thờ duy nhất Phật Thích Ca" class="wp-image-3450"/><figcaption>Chùa dơi chỉ thờ duy nhất Phật Thích Ca</figcaption></figure>



<h3 class="wp-block-heading">Kinh nghiệm du lịch chùa Dơi</h3>



<p>Khi tham quan chùa Dơi bạn nên tránh mặc đồ quá hở hang. Tuy là chùa Khmer nhưng vẫn cần giữ sự tôn nghiêm khi tham quan chùa. Bạn nên tránh dùng đá hay vật cứng chọi, chọc phá những con dơi đang ngủ trên cây.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="861" src="https://media.huynhhieutravel.com/nơi-thờ-Phật-chùa-dơi-1024x861.jpg" alt="Nơi thờ Phật chùa Dơi" class="wp-image-3465"/><figcaption>Nơi thờ Phật chùa Dơi</figcaption></figure>



<p>Ngoài ra, bạn có thể tham khảo chi tiết các điểm du lịch và cách du lịch Sóc Trăng tại đây: <a href="https://huynhhieutravel.com/du-lich-soc-trang" target="_blank" rel="noreferrer noopener" aria-label="https://huynhhieutravel.com/du-lich-soc-trang (mở trong tab mới)">https://huynhhieutravel.com/du-lich-soc-trang</a></p>



<p>Địa chỉ chùa Dơi: Văn Ngọc Chính, Phường 3, Sóc Trăng, Việt Nam.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15736.756898027304!2d105.96371545242329!3d9.578951427436754!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xe524b0c8be590a88!2zQ2jDuWEgRMahaQ!5e0!3m2!1svi!2s!4v1545373176327" width="600" height="450" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Tour du lịch</h2>



<p>Thông thường ta sẽ có những Tour du lịch khám phá ba ngôi chùa đặc trưng Sóc Trăng và kết hợp cả khám phá Bạc Liêu. Bạn có thể xem chi tiết Tour du lịch Sóc Trăng, Bạc Liêu từ Cần Thơ tại <a rel="noreferrer noopener" aria-label="đây (mở trong tab mới)" href="https://nucuoimekong.com/tour/can-tho-soc-trang-bac-lieu-ca-mau-2-ngay-1-dem/" target="_blank">đây</a>.</p>
', 'Chùa Dơi Sóc Trăng là một ngôi chùa đặc biệt bởi các con dơi sinh sống trong khuôn viên chùa. Thật ra cái tên chùa Dơi là do dân gian gọi tên để dễ nhớ hơn. Còn cái tên thật của nó là Serây tê chô mahatúp (Còn có nghĩa tiếng Việt là Trận Kháng [&hellip;]', 3455, 'post', '2019-02-07 23:50:40', '2023-04-23 12:43:04');

